def sbom(components, dependencies=None, metadata=None):
    document = {
        "bomFormat": "CycloneDX",
        "specVersion": "1.5",
        "components": components,
    }
    if dependencies is not None:
        document["dependencies"] = dependencies
    if metadata is not None:
        document["metadata"] = metadata
    return document


def component(ref, purl, **extra):
    entry = {"bom-ref": ref, "purl": purl}
    entry.update(extra)
    return entry


class PurlParsingTests(unittest.TestCase):
    def test_pypi(self) -> None:
        self.assertEqual(parse_purl("pkg:pypi/django@4.0.0"), ("pypi", "django", "4.0.0"))

    def test_npm_unscoped(self) -> None:
        self.assertEqual(parse_purl("pkg:npm/react@18.3.1"), ("npm", "react", "18.3.1"))

    def test_npm_scoped(self) -> None:
        self.assertEqual(
            parse_purl("pkg:npm/%40scope/pkg@1.0.0"), ("npm", "@scope/pkg", "1.0.0")
        )

    def test_percent_encoding_restored(self) -> None:
        self.assertEqual(
            parse_purl("pkg:pypi/my%2Dpkg@1%2E0%2E0"), ("pypi", "my-pkg", "1.0.0")
        )

    def test_percent_encoding_hex_case_insensitive(self) -> None:
        self.assertEqual(
            parse_purl("pkg:pypi/lib%2dcore@1%2e0"), ("pypi", "lib-core", "1.0")
        )

    def test_percent_decoding_happens_once(self) -> None:
        # %25 decodes to a literal % that is not decoded again.
        self.assertEqual(
            parse_purl("pkg:pypi/foo%2525@1"), ("pypi", "foo%25", "1")
        )

    def test_broken_percent_escape_rejected(self) -> None:
        for bad in (
            "pkg:pypi/foo%@1",
            "pkg:pypi/foo%A@1",
            "pkg:pypi/foo%GG@1",
            "pkg:pypi/foo@1%",
            "pkg:pypi/foo@1%2",
            "pkg:p%pi/foo@1",
            "pkg:npm/%40scope/p%41g%@1",
        ):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    parse_purl(bad)

    def test_undecodable_utf8_bytes_rejected(self) -> None:
        for bad in (
            "pkg:pypi/foo%FF@1",
            "pkg:pypi/foo%E4%B8@1",
            "pkg:pypi/foo@1%FF",
        ):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    parse_purl(bad)

    def test_percent_in_qualifiers_and_subpath_ignored(self) -> None:
        self.assertEqual(
            parse_purl("pkg:pypi/foo@1?arch=%GG#frag%"), ("pypi", "foo", "1")
        )

    def test_type_is_case_insensitive(self) -> None:
        self.assertEqual(parse_purl("pkg:PyPI/foo@1"), ("pypi", "foo", "1"))

    def test_missing_version_rejected(self) -> None:
        with self.assertRaises(ValueError):
            parse_purl("pkg:pypi/foo")

    def test_unsupported_ecosystem_rejected(self) -> None:
        with self.assertRaises(ValueError):
            parse_purl("pkg:maven/org.example/foo@1.0")

    def test_malformed_rejected(self) -> None:
        for bad in ("not-a-purl", "pkg:", "pkg:pypi/", "pkg:pypi/foo@", "pkg:pypi/@1"):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    parse_purl(bad)

    def test_pypi_namespace_rejected(self) -> None:
        with self.assertRaises(ValueError):
            parse_purl("pkg:pypi/namespace/foo@1")

    def test_empty_name_segment_rejected(self) -> None:
        # Empty segments are never silently dropped: consecutive slashes or a
        # trailing slash before the version separator reject the purl.
        for bad in (
            "pkg:pypi//foo@1",
            "pkg:pypi/foo/@1",
            "pkg:pypi/foo//bar@1",
            "pkg:npm//pkg@1",
            "pkg:npm/%40scope//pkg@1",
            "pkg:npm/%40scope/pkg/@1",
        ):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    parse_purl(bad)

    def test_decoded_slash_in_name_segment_rejected(self) -> None:
        # A percent-encoded slash must not smuggle extra hierarchy into a
        # name segment, whatever the hex digit case.
        for bad in (
            "pkg:pypi/team%2Ffoo@1",
            "pkg:pypi/team%2ffoo@1",
            "pkg:npm/%40scope%2Fpkg@1",
            "pkg:npm/foo%2Fbar@1",
        ):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    parse_purl(bad)

    def test_double_encoded_slash_is_literal_text(self) -> None:
        # %252F decodes exactly once to the literal text %2F, which is not a
        # slash and must not be rejected as one.
        self.assertEqual(
            parse_purl("pkg:pypi/foo%252F@1"), ("pypi", "foo%2F", "1")
        )


