    ],
    "dependencies": [{"ref": "a1", "dependsOn": ["a2"]}],
})
print("components before:", cat.connection.execute("SELECT name FROM components").fetchall())

# Inject a write failure during component-saving phase: make INSERT INTO components fail.
orig = cat.connection.execute
def failing(sql, *params):
    if isinstance(sql, str) and sql.lstrip().upper().startswith("INSERT INTO COMPONENTS"):
        raise sqlite3.OperationalError("simulated disk I/O error")
    return orig(sql, *params)
cat.connection.execute = failing

new_doc = {
    "bomFormat": "CycloneDX", "specVersion": "1.5",
    "components": [
        {"bom-ref": "n1", "purl": "pkg:pypi/app@1.0.0"},
        {"bom-ref": "n2", "purl": "pkg:pypi/libnew@3.0.0"},
    ],
    "dependencies": [{"ref": "n1", "dependsOn": ["n2"]}],
}
try:
    cat.import_sbom("api", "src-a", new_doc)
    print("IMPORT SUCCEEDED UNEXPECTEDLY")
except Exception as e:
    print("import raised:", type(e).__name__, e)
print("components after:", [r[0] for r in cat.connection.execute("SELECT name FROM components")])
print("component_sources:", cat.connection.execute("SELECT cs.component_id, c.name FROM component_sources cs JOIN components c ON c.id=cs.component_id").fetchall())
